package com.picviewer.core;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
public class CoreTest {
 Photo p(String path){return new Photo(path,4,10);}
 @Test public void naturalSortOverflowAndLeadingZeros(){List<String> s=new ArrayList<>(Arrays.asList("사진10.jpg","사진2.jpg","사진999999999999999999999999999.jpg","사진0001.jpg"));s.sort(Paths::natural);assertEquals("사진0001.jpg",s.get(0));assertEquals("사진2.jpg",s.get(1));assertEquals("사진10.jpg",s.get(2));}
 @Test public void pathsRejectTraversal(){assertEquals("photos/여행",Paths.normalize("\\photos\\여행\\"));try{Paths.normalize("a/../b");fail();}catch(IllegalArgumentException expected){}}
 @Test public void parentChildSelectionAndPartialStates(){Selection s=new Selection();s.all("",true);Set<String> folders=new HashSet<>(Arrays.asList("","a","a/b","a/c","d"));s.set("a/b",false);assertEquals(2,s.state("a",folders));assertEquals(2,s.state("",folders));assertFalse(s.includes("a/b/new"));assertTrue(s.includes("a/c/new"));s.set("a",true);assertEquals(1,s.state("a",folders));assertTrue(s.includes("a/b/new"));}
 @Test public void noDuplicateFromOverlappingSelections(){Selection s=new Selection();s.set("a",true);s.set("a/b",true);List<Photo> a=s.filter(Arrays.asList(p("a/b/1.jpg"),p("a/b/1.jpg"),p("other/2.jpg")));assertEquals(1,a.size());}
 @Test public void nonRecursiveSelectsOnlyDirectFiles(){Selection s=new Selection();s.recursive=false;s.set("a",true);assertEquals(1,s.filter(Arrays.asList(p("a/1.jpg"),p("a/b/2.jpg"))).size());}
 @Test public void newChildrenInheritButNotSiblings(){Selection s=new Selection();s.set("a",true);assertTrue(s.includes("a/new"));assertFalse(s.includes("b"));}
 @Test public void shuffleCycleNoRepeatsAndBoundaryNoRepeat(){List<Photo> a=new ArrayList<>();for(int i=0;i<100;i++)a.add(p("a/"+i+".jpg"));Playlist q=new Playlist(true,55);q.reset(a,null);Set<String> visited=new HashSet<>();for(int i=0;i<100;i++){assertTrue(visited.add(q.current()));if(i<99)q.next(a);}String end=q.current();String start=q.next(a);assertNotEquals(end,start);assertEquals(100,new HashSet<>(q.order).size());}
 @Test public void playlistAddsNextCycleRemovesImmediately(){List<Photo> a=Arrays.asList(p("a/1.jpg"),p("a/2.jpg"));Playlist q=new Playlist(false,1);q.reset(a,null);q.reconcile(Arrays.asList(p("a/1.jpg"),p("a/3.jpg")));assertEquals(Collections.singletonList("a/1.jpg"),q.order);q.next(Arrays.asList(p("a/1.jpg"),p("a/3.jpg")));assertEquals(2,q.order.size());}
 @Test public void restoreQueueCurrentAndCycle(){Playlist q=new Playlist(true,7);q.restore(Arrays.asList("a","b","c"),1,4);assertEquals("b",q.current());assertEquals(4,q.cycle);}
 @Test public void emptySingleRandom(){Playlist q=new Playlist(true,1);q.reset(Collections.emptyList(),null);assertNull(q.next(Collections.emptyList()));q.reset(Collections.singletonList(p("1.jpg")),null);for(int i=0;i<5;i++)assertEquals("1.jpg",q.next(Collections.singletonList(p("1.jpg"))));}
 Scanner.Entry e(String name,boolean folder){return new Scanner.Entry(name,folder,false,10,20);}
 @Test public void scanRecursesAndRemovesDeletedButPreservesFailedSubtree(){List<Photo> old=Arrays.asList(p("good/deleted.jpg"),p("bad/keep.jpg"),p("gone/old.jpg"));Set<String> dirs=new HashSet<>(Arrays.asList("","good","bad","gone"));Scanner.Source source=path->{if(path.isEmpty())return Arrays.asList(e("good",true),e("bad",true));if(path.equals("bad"))throw new Exception("denied");return Arrays.asList(e("new.jpg",false),e("not-image.txt",false));};Scanner.Result r=Scanner.scan(source,"",old,dirs,new AtomicBoolean(),null);assertEquals(2,r.photos.size());assertTrue(r.photos.stream().anyMatch(p->p.path.equals("bad/keep.jpg")));assertTrue(r.photos.stream().anyMatch(p->p.path.equals("good/new.jpg")));assertFalse(r.folders.contains("gone"));assertEquals(Collections.singleton("bad"),r.failed);}
 @Test public void failedRootCannotDeleteInventory(){List<Photo> old=Arrays.asList(p("a/keep.jpg"));Scanner.Result r=Scanner.scan(path->{throw new Exception();},"",old,new HashSet<>(Arrays.asList("","a")),new AtomicBoolean(),null);assertEquals(old,r.photos);}
 @Test public void cancelledCannotPretendComplete(){AtomicBoolean stop=new AtomicBoolean(true);Scanner.Result r=Scanner.scan(path->Collections.emptyList(),"",Collections.emptyList(),Collections.emptySet(),stop,null);assertTrue(r.cancelled);assertFalse(r.complete());}
 @Test public void linksAndMaliciousNamesIgnored(){Scanner.Source s=path->Arrays.asList(new Scanner.Entry("cycle",true,true,0,0),e("../escape.jpg",false),e("ok.png",false));Scanner.Result r=Scanner.scan(s,"",Collections.emptyList(),Collections.emptySet(),new AtomicBoolean(),null);assertEquals(1,r.photos.size());assertEquals("ok.png",r.photos.get(0).path);}
 @Test public void cacheKeysChangeWithSourceAndMetadata(){assertNotEquals(p("a.jpg").key("s1"),p("a.jpg").key("s2"));assertNotEquals(p("a.jpg").key("s1"),new Photo("a.jpg",10,11).key("s1"));}
 @Test public void fileFormatsCaseInsensitive(){assertTrue(Photo.candidate("a.CR3"));assertTrue(Photo.candidate("x.HeIc"));assertFalse(Photo.candidate("readme.txt"));}
 @Test public void largeIndex10000(){List<Photo> a=new ArrayList<>();for(int i=0;i<10000;i++)a.add(p("a/"+i+".jpg"));Selection s=new Selection();s.all("",true);assertEquals(10000,s.filter(a).size());Playlist q=new Playlist(true,8);q.reset(a,null);assertEquals(10000,new HashSet<>(q.order).size());}
}
